import{_ as t,o,c as i,ag as a}from"./chunks/framework.B9unkguw.js";const s="/master/assets/app_log_viewer.Cc04db9F.jpg",u=JSON.parse('{"title":"Console Logging","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/troubleshooting/console_logging.md","filePath":"en/qgc-user-guide/troubleshooting/console_logging.md"}'),n={name:"en/qgc-user-guide/troubleshooting/console_logging.md"};function l(r,e,g,d,p,c){return o(),i("div",null,e[0]||(e[0]=[a('<h1 id="console-logging" tabindex="-1">Console Logging <a class="header-anchor" href="#console-logging" aria-label="Permalink to &quot;Console Logging&quot;">​</a></h1><p>The <em>App Log Viewer</em> can be a helpful tool for diagnosing <em>QGroundControl</em> problems. It can be found in <strong>Application Settings &gt; App Log Viewer</strong>.</p><p><img src="'+s+`" alt="App Log Viewer"></p><p>Click the <strong>Categories</strong> button to enable/disable the logging categories displayed by <em>QGroundControl</em>.</p><h2 id="common-logging-categories" tabindex="-1">Common Logging Categories <a class="header-anchor" href="#common-logging-categories" aria-label="Permalink to &quot;Common Logging Categories&quot;">​</a></h2><p>The most commonly used logging categories are listed below.</p><table tabindex="0"><thead><tr><th>Category(s)</th><th>Description</th></tr></thead><tbody><tr><td><code>Comms.LinkManager</code>, <code>Vehicle.MultiVehicleManager</code></td><td>Debug connection problems.</td></tr><tr><td><code>Comms.LinkManager:verbose</code></td><td>Debug serial ports not being detected. Very noisy continuous output of available serial ports.</td></tr><tr><td><code>VehicleSetup.FirmwareUpgrade</code></td><td>Debug firmware flash issues.</td></tr><tr><td><code>FactSystem.ParameterManager</code></td><td>Debug parameter load problems.</td></tr><tr><td><code>FactSystem.ParameterManager:debugCacheFailure</code></td><td>Debug parameter cache crc misses.</td></tr><tr><td><code>PlanManager.PlanManager</code>, <code>PlanManager.MissionManager</code>, <code>PlanManager.GeoFenceManager</code>, <code>PlanManager.RallyPointManager</code></td><td>Debug Plan upload/download issues.</td></tr><tr><td><code>AutoPilotPlugins.RadioComponentController</code></td><td>Debug Radio calibration issues.</td></tr></tbody></table><h2 id="logging-from-the-command-line" tabindex="-1">Logging from the Command Line <a class="header-anchor" href="#logging-from-the-command-line" aria-label="Permalink to &quot;Logging from the Command Line&quot;">​</a></h2><p>An alternate mechanism for logging is using the <code>--logging</code> command line option. This is handy if you are trying to get logs from a situation where <em>QGroundControl</em> crashes.</p><p>Two options work together:</p><ul><li><code>--logging:full</code> (or <code>--logging:&lt;comma-separated categories&gt;</code>) enables the logging categories.</li><li><code>--log-output</code> writes the log messages to stderr (the terminal on macOS/Linux). Without it, messages are only visible in the <em>App Log Viewer</em> and the <strong>AppLog.log</strong> file in the application log directory.</li></ul><p>How you do this and where the traces are output vary by OS:</p><ul><li><p>Windows</p><ul><li><p>Open a command prompt and run <em>QGroundControl</em> from its install location (the installer default is shown below). Because <em>QGroundControl</em> is a GUI application it has no console window, so stderr isn&#39;t displayed — redirect it to a file to capture it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%ProgramFiles%\\QGroundControl\\bin&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">QGroundControl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%USERPROFILE%\\qgc_log.txt&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div></li></ul></li><li><p>macOS</p><ul><li><p>You must run <em>QGroundControl</em> from Terminal. The Terminal app is located in <strong>Applications/Utilities</strong>. Once Terminal is open paste the following into it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/QGroundControl.app/Contents/MacOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./QGroundControl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span></span></code></pre></div></li><li><p>Log traces will output to the Terminal window.</p></li></ul></li><li><p>Linux</p><ul><li><p>Run the AppImage from a terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./QGroundControl-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;arch&gt;.AppImage </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--logging:full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-output</span></span></code></pre></div></li><li><p>Log traces will output to the shell you are running from.</p></li></ul></li></ul>`,13)]))}const m=t(n,[["render",l]]);export{u as __pageData,m as default};
